local ChainmailForger = {}
local PRODUCTS = {
    simple_iron_chainmail = { name = "Preprost železni verižni oklep", ironCost = 4, leatherCost = 1, time = 6, cost = 200, defense = 30, happiness = 1, description = "Preprost železni verižni oklep za vojake." },
    steel_riveted_chainmail = { name = "Jekleno zakovučeni verižni oklep", ironCost = 4, steelCost = 2, leatherCost = 1, time = 9, cost = 520, defense = 45, happiness = 2, prestige = 4, description = "Jekleno zakovučeni verižni oklep za viteze." },
    silver_trimmed_chainmail = { name = "Srebrnoobrobljeni verižni oklep", ironCost = 4, silverCost = 2, steelCost = 1, leatherCost = 1, time = 12, cost = 1100, defense = 58, happiness = 2, prestige = 10, description = "Srebrnoobrobljeni verižni oklep za plemiške viteze." },
    gold_inlaid_chainmail = { name = "Zlatovloženi verižni oklep", ironCost = 4, goldCost = 2, silverCost = 1, steelCost = 1, leatherCost = 1, time = 16, cost = 2400, defense = 70, happiness = 3, prestige = 20, description = "Zlatovloženi verižni oklep za visoke plemiče." },
    jewel_pinned_chainmail = { name = "Draguljnoprity verižni oklep", ironCost = 4, goldCost = 2, silverCost = 1, steelCost = 1, leatherCost = 1, jewelCost = 1, time = 20, cost = 5000, defense = 82, happiness = 5, prestige = 35, description = "Verižni oklep s draguljnimi priponkami za visoko plemstvo." },
    royal_grand_chainmail = { name = "Kraljevski veliki verižni oklep", ironCost = 6, goldCost = 3, silverCost = 2, steelCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 28, cost = 9000, defense = 95, happiness = 12, prestige = 65, description = "Veliki kraljevski verižni oklep z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    chain_workshop = { name = "Verižna delavnica", cost = { gold = 280, wood = 120, stone = 140, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    mail_loft = { name = "Verižna podstrešje", cost = { gold = 1100, wood = 280, stone = 320, steel = 6, leather = 6 }, upkeep = 26, qualityBonus = 18 },
    master_armorer_atelier = { name = "Mojstrski okleparski atelje", cost = { gold = 3000, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 70, qualityBonus = 30 },
    royal_chain_palace = { name = "Kraljevska verižna palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
ChainmailForger.ironStock = 18; ChainmailForger.steelStock = 12; ChainmailForger.leatherStock = 10; ChainmailForger.silverStock = 8; ChainmailForger.goldStock = 6; ChainmailForger.jewelStock = 4; ChainmailForger.pearlStock = 4
ChainmailForger.productStock = {}; ChainmailForger.buildings = {}; ChainmailForger.maker = nil; ChainmailForger.activeMaking = {}; ChainmailForger.totalProducts = 0; ChainmailForger.dayTimer = 0
function ChainmailForger.init() ChainmailForger.ironStock=18; ChainmailForger.steelStock=12; ChainmailForger.leatherStock=10; ChainmailForger.silverStock=8; ChainmailForger.goldStock=6; ChainmailForger.jewelStock=4; ChainmailForger.pearlStock=4; ChainmailForger.productStock={}; ChainmailForger.buildings={}; ChainmailForger.maker=nil; ChainmailForger.activeMaking={}; ChainmailForger.totalProducts=0; ChainmailForger.dayTimer=0; print("[ChainmailForger] Royal Chainmail Forger System initialized (6 products, 4 buildings)") end
function ChainmailForger.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChainmailForger.maker={name=n or ("Verižar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Verižar najet: %s (spretnost: %d)",ChainmailForger.maker.name,s),"success") end; return true end
function ChainmailForger.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChainmailForger.build(id) local ok,e=ChainmailForger.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChainmailForger.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChainmailForger.getQualityBonus() local b=0; for _,bd in ipairs(ChainmailForger.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChainmailForger.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ChainmailForger.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and ChainmailForger.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.leatherCost and ChainmailForger.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ChainmailForger.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChainmailForger.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChainmailForger.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChainmailForger.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChainmailForger.buildings==0 then return false,"Potrebna verižna delavnica" end; if not ChainmailForger.maker then return false,"Potreben verižar" end; return true end
function ChainmailForger.make(pt,qty) qty=qty or 1; local ok,e=ChainmailForger.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ChainmailForger.ironStock=ChainmailForger.ironStock-d.ironCost*qty end; if d.steelCost then ChainmailForger.steelStock=ChainmailForger.steelStock-d.steelCost*qty end; if d.leatherCost then ChainmailForger.leatherStock=ChainmailForger.leatherStock-d.leatherCost*qty end; if d.silverCost then ChainmailForger.silverStock=ChainmailForger.silverStock-d.silverCost*qty end; if d.goldCost then ChainmailForger.goldStock=ChainmailForger.goldStock-d.goldCost*qty end; if d.jewelCost then ChainmailForger.jewelStock=ChainmailForger.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChainmailForger.pearlStock=ChainmailForger.pearlStock-d.pearlCost*qty end; local t=d.time; if ChainmailForger.maker then t=math.max(1,t-math.floor(ChainmailForger.maker.skill/12)) end; table.insert(ChainmailForger.activeMaking,{id="chainmail_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChainmailForger.completeMaking(m) local q=1.0+(ChainmailForger.getQualityBonus()/100); if ChainmailForger.maker then q=q+(ChainmailForger.maker.skill/140) end; q=math.min(2.5,q); ChainmailForger.productStock[m.productType]=(ChainmailForger.productStock[m.productType] or 0)+m.quantity; ChainmailForger.totalProducts=ChainmailForger.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChainmailForger.maker then ChainmailForger.maker.itemsMade=ChainmailForger.maker.itemsMade+m.quantity; if math.random()<0.25 then ChainmailForger.maker.skill=math.min(100,ChainmailForger.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Verižni oklep izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chainmail.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function ChainmailForger.update(dt) if not _G.state then return end; ChainmailForger.dayTimer=ChainmailForger.dayTimer+dt; if ChainmailForger.dayTimer>=30 then ChainmailForger.dayTimer=0; for i=#ChainmailForger.activeMaking,1,-1 do local m=ChainmailForger.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChainmailForger.completeMaking(m); table.remove(ChainmailForger.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChainmailForger.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChainmailForger.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChainmailForger.getStats() return {ironStock=ChainmailForger.ironStock,steelStock=ChainmailForger.steelStock,leatherStock=ChainmailForger.leatherStock,silverStock=ChainmailForger.silverStock,goldStock=ChainmailForger.goldStock,jewelStock=ChainmailForger.jewelStock,pearlStock=ChainmailForger.pearlStock,productStock=ChainmailForger.productStock,numBuildings=#ChainmailForger.buildings,hasMaker=ChainmailForger.maker~=nil,makerName=ChainmailForger.maker and ChainmailForger.maker.name or "—",makerSkill=ChainmailForger.maker and ChainmailForger.maker.skill or 0,activeMaking=#ChainmailForger.activeMaking,totalProducts=ChainmailForger.totalProducts} end
return ChainmailForger
